<?php
require_once __DIR__ . '/../../app/auth.php';
require_once __DIR__ . '/../components/metrics.php';
if (empty($_SESSION['emailadm'])) { header('Location: '.app_url('adm/login/'), true, 303); exit; }
$db=app_db();
$stats=admin_metrics($db);
$rows=$db->query("SELECT email,externalreference,valor,status,data FROM confirmar_deposito
    ORDER BY STR_TO_DATE(data, '%d/%m/%Y %H:%i') DESC LIMIT 200")->fetch_all(MYSQLI_ASSOC);
$db->close();
$adminActive='depositos'; $adminTitle='Depósitos';
$statusLabel=static function(string $status): string {
    return ['PAID_OUT'=>'Confirmado','WAITING_FOR_APPROVAL'=>'Aguardando','CANCELED'=>'Cancelado','REVIEW'=>'Conferir'][$status] ?? 'Conferir';
};
$statusClass=static function(string $status): string { return $status==='PAID_OUT'?'paid':($status==='CANCELED'?'canceled':'pending'); };
